xql_query:
// ============================================================
// Rule: IPV_Removing SSL from Site
// Vendor: Imperva
// Objective:
// Detect activity associated with IPV_Removing SSL from Site.
// Severity: SEV_040_HIGH
// Category: EVASION
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion

// Configuração inicial: define que as comparações NÃO diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variação de caixa em campos textuais como 'message'
config case_sensitive = false

// Fonte de dados: logs brutos do Imperva WAF
// O dataset 'imperva_waf_raw' armazena eventos operacionais e de auditoria do Imperva,
// incluindo ações administrativas realizadas via console (audit trail)
| dataset = imperva_waf_raw

// Extração e normalização de campos a partir do payload JSON do Imperva
// Observação: o campo 'imperva' contém o JSON bruto do evento (ajuste o nome se necessário)
// - resource_name: identifica o recurso impactado (ex.: site/hostname removido)
// - account_name: identifica a conta/tenant do Imperva onde a ação ocorreu
// - executor: usuário administrativo que executou a ação no console
| alter
    resource_name = json_extract_scalar(imperva, "$.audit_trail.resource_name"), // Ex.: <INTERNAL_DOMAIN_25>.br
    account_name  = json_extract_scalar(imperva, "$.ids.account_name"),          // Ex.: BRA - <ORGANIZATION> - CWAF
    executor      = user -> email                                                // Executor da ação administrativa

| filter (message = """Removing SSL from site""") 

// Seleção dos campos relevantes para auditoria, correlação e notificação do alerta
| fields
    user,           // Estrutura original do usuário (id, nome, e-mail, conforme disponível)
    executor,       // E-mail do administrador que realizou a remoção
    account_name,   // Conta/tenant afetada no Imperva
    resource_name,  // Site/hostname removido
    message,        // Ação executada (remoção do site)
    imperva         // Payload bruto do evento (evidência para investigação e troubleshooting)
